// pubspec.yaml:
//   flutter_riverpod: ^2.5.0
//   riverpod_annotation: ^2.3.0
// dev_dependencies:
//   riverpod_generator: ^2.4.0
//   build_runner: ^2.4.8

import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:riverpod_annotation/riverpod_annotation.dart';
part 'feed.g.dart';

// ────── Repository DI ──────
@Riverpod(keepAlive: true)
FeedRepository feedRepository(FeedRepositoryRef ref) => FeedRepository(ref.watch(apiProvider));

// ────── Family + autoDispose (screen-scoped) ──────
@riverpod
Future<List<Item>> feed(FeedRef ref, {String query = ''}) async {
  final repo = ref.watch(feedRepositoryProvider);
  final cancel = CancelToken();
  ref.onDispose(cancel.cancel);   // GC → cancel in-flight
  return repo.search(query, cancel: cancel);
}

// ────── Mutable AsyncNotifier ──────
@riverpod
class CartController extends _$CartController {
  @override
  FutureOr<Cart> build() async {
    // First read — load initial cart from disk.
    return ref.watch(cartStorageProvider).load();
  }

  Future<void> add(Item i) async {
    state = const AsyncLoading();
    state = await AsyncValue.guard(() async {
      final updated = (state.valueOrNull ?? const Cart.empty()).plus(i);
      await ref.read(cartStorageProvider).save(updated);
      return updated;
    });
  }
}

// ────── UI ──────
void main() => runApp(const ProviderScope(child: MyApp()));

class FeedScreen extends ConsumerStatefulWidget {
  const FeedScreen({super.key});
  @override ConsumerState<FeedScreen> createState() => _FeedScreenState();
}
class _FeedScreenState extends ConsumerState<FeedScreen> {
  String _q = '';
  @override
  Widget build(BuildContext context) {
    // AsyncValue<List<Item>> — handles loading/data/error cleanly.
    final asyncItems = ref.watch(feedProvider(query: _q));

    // React to side effects — logout, error toast.
    ref.listen(authControllerProvider, (prev, next) {
      if (next.value?.isLoggedOut == true) context.go('/login');
    });

    return Scaffold(
      appBar: AppBar(title: const Text('Feed')),
      body: Column(children: [
        TextField(onChanged: (q) => setState(() => _q = q)),
        Expanded(child: asyncItems.when(
          data: (items) => ListView(children: items.map(ItemTile.new).toList()),
          loading: () => const Center(child: CircularProgressIndicator()),
          error: (e, s) => Center(child: Text('$e')),
        )),
      ]),
    );
  }
}

// Regen: dart run build_runner watch --delete-conflicting-outputs

// AsyncValue models loading / data / error in ONE sealed type.
final AsyncValue<User> u = ref.watch(userProvider);

// Pattern-match:
u.when(
  data: (user) => Text(user.name),
  loading: () => const CircularProgressIndicator(),
  error: (e, st) => Text('Error: $e'),
);

// Or with switch:
switch (u) {
  AsyncData(:final value) => Text(value.name),
  AsyncLoading() => const CircularProgressIndicator(),
  AsyncError(:final error) => Text('$error'),
  _ => const SizedBox(),
}

// Composition: derived AsyncValue that combines two sources.
final fullProfile = FutureProvider<FullProfile>((ref) async {
  final u = await ref.watch(userProvider.future);
  final s = await ref.watch(settingsProvider.future);
  return FullProfile(u, s);
});
// If EITHER dep is loading, `fullProfile` is loading — no manual flag juggling.
